// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: fund a user with 1 ether
        address user = address(0x1234);
        vm.deal(user, 1 ether);

        // Step 2: set MinSum to 100 via SetMinSum before initialization
        vm.prank(user);
        c.SetMinSum(100);

        // Step 3: Initialize (so that SetMinSum can no longer change MinSum)
        vm.prank(user);
        c.Initialized();

        // Step 4: user deposits 1 ether with locktime 0
        vm.prank(user);
        c.Put{value: 1 ether}(0);

        // Step 5: warp time past unlock (unlockTime = block.timestamp + 0 = block.timestamp, so warp to block.timestamp + 1)
        vm.warp(block.timestamp + 1);

        // Step 6: call Collect(100) - this should succeed in reference (MinSum=100, user has >=100 balance) 
        // but in buggy version SetMinSum set MinSum to 0, so the condition acc.balance>=MinSum fails? 
        // Actually 0 is smaller, so Collect would succeed. Let's check MinSum state instead.

        // The observable difference: after SetMinSum but before init, reference has MinSum=100, bug has MinSum=0.
        // At this point, c.MinSum() should be 100 in reference.
        uint minSumVal = c.MinSum();
        // In reference: minSumVal == 100; In bug: minSumVal == 0.
        assertTrue(minSumVal == 100, "MinSum should be 100 in reference");
    }
}

