pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up actors
        address user = address(0x123);

        // Call SetMinSum(100) before initialization
        c.SetMinSum(100);

        // Call Put(0) to set unlockTime (needed for Collect to succeed if MinSum <= balance)
        vm.prank(user);
        c.Put(0);

        // Warp past unlockTime (block.timestamp + 0 is block.timestamp, so any later time works)
        vm.warp(block.timestamp + 1);

        // Collect(100) — user has 0 balance, so if MinSum is 100 the require fails;
        // if MinSum is 0 the require passes and Collect tries to send 0 ether
        vm.prank(user);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 100));

        // After Collect, MinSum must differ
        bool refCondition = (c.MinSum() == 100);  // reference: SetMinSum(100) kept MinSum=100
        // But in buggy M, MinSum was set to 0 in SetMinSum, so MinSum() == 0
        assertTrue(refCondition);
    }
}

