        c.Initialized();
        // User (address(this)) calls Collect with 1 ether, has 0 balance
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // Reference reverts because MinSum=1e18 > balance=0; buggy version does not revert because MinSum=0
        assertTrue(!ok, "Collect should revert in reference");
    }
}

