        vm.prank(address(0x1));
        c.Initialized();
        vm.prank(address(0x1));
        // try SetMinSum: in reference it reverts, in buggy it succeeds
        bool setSucceeded = false;
        try c.SetMinSum(1) { setSucceeded = true; } catch { setSucceeded = false; }
        // Now user A puts 1 wei with _lockTime=0 (so unlockTime > block.timestamp is false, timelock not a factor)
        vm.deal(address(0x2), 1 wei);
        vm.prank(address(0x2));
        c.Put{value: 1 wei}(0);
        warp to block.timestamp+1 so unlockTime check passes
        vm.warp(block.timestamp + 1);
        // Try Collect(1) from user A
        bool collectSucceeded = false;
        vm.prank(address(0x2));
        try c.Collect(1) { collectSucceeded = true; } catch { collectSucceeded = false; }
        // Assert that in reference Collect reverts (setSucceeded==false), in buggy it succeeds (setSucceeded==true)
        // Actually we check the divergence: reference: collectSucceeded==false, buggy: collectSucceeded==true
        // But we need a one-assertion that shows difference: we can assert that collectSucceeded == setSucceeded
        // Because in reference, setSucceeded==false and collectSucceeded==false -> equal; in buggy, both true -> equal? No, buggy: setSucceeded==true, collectSucceeded==true -> equal too? Wait, buggy: setSucceeded==true, and because MinSum becomes 1, collectSucceeded==true. So both are equal. That doesn't break. Hmm.
        // Let's reconsider: reference: setSucceeded==false, MinSum==0 -> Collect(1) reverts -> collectSucceeded==false. Buggy: setSucceeded==true, MinSum==1 -> Collect(1) succeeds -> collectSucceeded==true. So they differ. Assert that setSucceeded != collectSucceeded? But in reference setSucceeded == collectSucceeded (both false), in buggy setSucceeded == collectSucceeded (both true) — still equal. Actually they both equal each other in both cases, so that assertion passes for both? No, for reference: false==false => true; for buggy: true==true => true. So that works? Wait, we want the assertion to FAIL on the buggy. But setSucceeded == collectSucceeded holds for both. So that doesn't fail.
        // We need an assertion that reference holds and buggy fails. Let's directly check that after SetMinSum, MinSum is 0 (reference) vs 1 (buggy) and then Collect result differs.
        uint minSumAfter = c.MinSum();
        if (minSumAfter == 0) {
            // reference case: assert Collect reverts
            vm.prank(address(0x2));
            try c.Collect(1) { assertTrue(false, "expected revert"); } catch { assertTrue(true); }
        } else {
            // buggy case: assert Collect succeeds
            vm.prank(address(0x2));
            try c.Collect(1) { assertTrue(true); } catch { assertTrue(false, "expected success"); }
        }
        // But the assertion must be a single assertTrue. Let's instead compute an x = (minSumAfter == 0 ? 0 : 1) and y = collectSucceeded? I think we need a single boolean expression that is true for reference and false for buggy. In reference: minSumAfter==0, collectSucceeded==false. In buggy: minSumAfter==1, collectSucceeded==true. The boolean (minSumAfter == 0) == (!collectSucceeded) holds for both? For reference: (true) == (true) = true; buggy: (false) == (false) = true. No. What about (minSumAfter == 0) && (collectSucceeded == false) ? For reference: true && true = true; buggy: false && false = false. Perfect!
        bool refBehavior = (c.MinSum() == 0) && (collectSucceeded == false);
        assertTrue(refBehavior, "Reference should have MinSum==0 and Collect revert");
    }
}

