pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call Initialized() so that SetMinSum in reference will revert
        c.Initialized();

        // Try SetMinSum(1) - reference reverts, buggy succeeds
        // We'll capture the MinSum value after the call by checking if it changed
        // Since reference reverts, actual value should be 0; if buggy succeeds, it becomes 1
        // Use try/catch to determine if SetMinSum succeeded
        bool setMinSumSucceeded;
        try c.SetMinSum(1) {
            setMinSumSucceeded = true;
        } catch {
            setMinSumSucceeded = false;
        }

        // Now set up conditions for Collect:
        // User A puts 1 wei with _lockTime=0
        address user = address(0x1);
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 1}(0);

        // Now try Collect(1)
        bool collectSucceeded;
        vm.prank(user);
        try c.Collect(1) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // The reference: SetMinSum fails -> MinSum stays 0 -> Collect(1) fails (balance<MinSum)
        // The buggy: SetMinSum succeeds -> MinSum = 1 -> Collect(1) succeeds
        // So we assert that collectSucceeded differs from setMinSumSucceeded
        // Specifically: setMinSumSucceeded == false in reference, true in buggy
        // and collectSucceeded == false in reference, true in buggy
        // They should have opposite truth values
        assertTrue(setMinSumSucceeded != collectSucceeded);
    }
}

