pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract
        c.Initialized();

        // Step 2: Set up a holder with balance and unlockTime
        // Use a specific user
        address user = address(0x1234);

        // Warp to time 1 to ensure block.timestamp > unlockTime (which defaults to 0)
        vm.warp(1);

        // Give user some ether and call Put with lockTime 0
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.Put{value: 0.5 ether}(0);

        // Now user has balance 0.5 ether, unlockTime = 1 (since warp to 1 + 0 = 1)
        // block.timestamp is 1, which is not > 1, so Collect won't work yet; warp to 2
        vm.warp(2);

        // Step 3: In the reference, SetMinSum cannot be called after Initialized, so MinSum stays 0
        // In the bug, SetMinSum can be called and sets MinSum to a value that prevents Collect
        // We call SetMinSum on the buggy version (but the reference reverts). 
        // We must test that the reference and bug diverge on Collect success.

        // Actually, we need to trigger the bug by calling SetMinSum after Initialized (which reference reverts)
        // But the test deploys a SINGLE contract; we cannot have both reference and bug in one contract.
        // The prompt says: "Driven through Collect, P and M differ in SetMinSum() value after Collect."
        // We must interpret: The scenario is that after Collect, reading SetMinSum() gives different values.
        // The bug allows SetMinSum to be called after Initialized, changing MinSum.
        // So we must simulate that the bug contract (M) allows SetMinSum after Init, while P reverts.
        // We can test this by checking that in P, calling SetMinSum after Init reverts, and in M it doesn't.
        // But the test deploys ONE contract; we need to check that the reference behavior (revert on SetMinSum after Init) happens.
        // The bug version would not revert. So we can test that the reference reverts, and the bug does not.

        // Set up prank to call SetMinSum after Init
        vm.prank(address(0xdead)); // any caller
        // In reference, this should revert. We'll catch it.
        bool ok;
        try c.SetMinSum(100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts -> ok = false
        // Bug does not revert -> ok = true
        // We assert that ok is false (reference behavior). The bug would have ok true.
        assertTrue(!ok, "SetMinSum should revert after Initialized");
    }
}

