// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract (sets intitalized = true, preventing further SetMinSum in reference)
        c.Initialized();

        // Step 2: In reference, this call is blocked (reverts); in bug, it succeeds, setting MinSum = 1
        c.SetMinSum(1);

        // Step 3: Set up caller with ether
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(0);

        // Step 4: Now attempt Collect(1 ether)
        // Reference: MinSum = 0, so acc.balance >= MinSum (1 >= 0) holds -> Collect succeeds
        // Bug: MinSum = 1, so acc.balance >= MinSum (1 >= 1) holds -> Collect also succeeds (but we need divergence)
        // Actually, with MinSum = 1, Collect still succeeds. We need MinSum > balance to cause revert.
        // Instead, use SetMinSum(2) to make bug's MinSum = 2, so balance (1) < MinSum (2), causing revert.
        // But we already called SetMinSum(1). Let's adjust: call SetMinSum(2) after initialization in bug only.
        // Since reference reverts on SetMinSum after initialization, MinSum stays 0.
        // Re-do: call SetMinSum(2) after Initialized(). In reference it reverts, but we ignore revert.
        // We need to capture the revert status of Collect.

        // Reset: call SetMinSum(2) — in reference this reverts (so MinSum remains 0), in bug it sets MinSum=2
        // But we can't call SetMinSum again because it's nonReentrant but not locked now — actually we can.
        // Let's do a clean sequence:
        // 1. Initialized() - sets intitalized = true
        // 2. SetMinSum(2) - in reference reverts (MinSum stays 0), in bug succeeds (MinSum = 2)
        // 3. alice Put(1 ether)
        // 4. Collect(1 ether) - in reference succeeds (MinSum=0, balance=1 >= 0), in bug reverts (MinSum=2, balance=1 < 2)

        // To handle the revert of SetMinSum in reference, we use try/catch:
        // Actually, we can just call it anyway — the reference reverts but we don't care, the state after is what matters.
        // But if reference reverts, the transaction fails, so the test would fail. We need to catch it.
        // Instead, we can use vm.prank and a separate call that reverts silently? No, revert stops the test.
        // Better approach: use try/catch around SetMinSum in the test.

        // RECALCULATION: Use a fresh approach without calling SetMinSum after Initialized in reference.
        // Instead, exploit the fact that in reference, SetMinSum is called BEFORE Initialized, then after Initialized it cannot change.
        // But the bug allows changing after. So:
        // 1. Initially MinSum = 0.
        // 2. Initialized() - no change to MinSum
        // 3. Put(1 ether) - balance = 1
        // 4. In reference, MinSum = 0, so Collect(1) succeeds (balance >= MinSum)
        // 5. In bug, call SetMinSum(2) after initialization -> MinSum = 2, then Collect(1) reverts (balance < MinSum)
        // So we need to make the SetMinSum call in the test but catch its revert in reference.

        // Let's wrap the SetMinSum call in a helper that ignores revert:
        bool setSucceeded;
        try c.SetMinSum(2) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        // Now do Put and Collect
        vm.prank(alice);
        c.Put{value: 1 ether}(0);

        bool collectSuccess;
        vm.prank(alice);
        try c.Collect(1 ether) {
            collectSuccess = true;
        } catch {
            collectSuccess = false;
        }

        // In reference, SetMinSum revert (setSucceeded false) so MinSum stays 0, Collect succeeds (true)
        // In bug, SetMinSum succeeds (setSucceeded true) so MinSum=2, Collect fails (false)
        // Assert that setSucceeded equals collectSuccess? No, we need a direct observation of divergence.
        // Actually we can assert that collectSuccess is true for reference and false for bug.
        // Since we are testing against the deployed contract c, which is either reference or bug, we just assert one value.
        // But the test must pass for reference and fail for bug. So we assert collectSuccess == true.
        // Reference: collectSuccess = true -> passes
        // Bug: collectSuccess = false -> fails
        assertTrue(collectSuccess);
    }
}

