pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: initialize and set minimum sum to 1 wei
        c.SetMinSum(1);
        c.Initialized();

        // Deploy a malicious contract that will reenter during Collect
        Reenterer reenterer = new Reenterer(address(c));

        // Fund the reenterer contract with 1 ether
        vm.deal(address(reenterer), 1 ether);

        // Reenterer puts 1 ether with lock=0 (so Collect is immediately available)
        vm.prank(address(reenterer));
        c.Put{value: 1 ether}(0);

        // Now call Collect via the Reenterer which will reenter during the call
        vm.prank(address(reenterer));
        try c.Collect(1 ether) {
            // First Collect succeeds (balance >= MinSum, block.timestamp > unlockTime)
            // But the reentrancy causes a second Collect inside
        } catch {}

        // Check if the reenterer's balance became 0 (bug) or remained non-zero (reference)
        // In reference, reentrancy is blocked => balance = 0 after successful Collect
        // In bug, reentrancy succeeds => balance underflow then second Collect drains
        // So we check if a third Collect would fail (balance=0) or succeed (underflow)
        // We'll use the test contract itself to do a final Collect check

        // Reset: fund test contract with 1 wei
        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        c.Put{value: 1 wei}(0);

        bool thirdCollectFailed;
        try c.Collect(1 wei) {
            thirdCollectFailed = false; // succeeded means bug
        } catch {
            thirdCollectFailed = true; // reverted means reference behavior
        }

        // In reference (correct), the second Collect in reentrancy is blocked,
        // so after first Collect, balance is 0, third Collect reverts => thirdCollectFailed == true
        // In bug (missing lock), reentrancy succeeds, balance underflows,
        // then the second Collect succeeds, draining more, so third Collect also succeeds => thirdCollectFailed == false
        // Assert that thirdCollectFailed is true (reference behavior)
        assertTrue(thirdCollectFailed);
    }
}

contract Reenterer {
    C public target;
    bool public attacked;

    constructor(address _target) {
        target = C(_target);
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            target.Collect(0.5 ether); // reenter with half the amount
        }
    }
}

